using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using RogControl;

public static class GearPowerGuiTests {
 static int checks;
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool valid,string message){checks++;if(!valid)throw new Exception(message);}
 static Dictionary<string,object> Obj(params object[] pairs){var map=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)map[(string)pairs[i]]=pairs[i+1];return map;}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string name,params object[] values){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,values);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){if(node==null)yield break;yield return node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i)))yield return child;}
 static DependencyObject Render(MainWindow window,string kind,string tab,int width){((Dictionary<string,string>)Field(window,"gearTabs"))[kind]=tab;Invoke(window,"ShowPage","device:"+kind);var root=(FrameworkElement)window.Content;root.Measure(new Size(width,826));root.Arrange(new Rect(0,0,width,826));root.UpdateLayout();return root;}
 static Dictionary<string,object> State(string kind){return Obj("deviceId","synthetic-"+kind,"online",true,"setCapabilities",new[]{"sleepMinutes","pollingRate"},"settingOptions",Obj("pollingRates",new[]{1000,8000}),"snapshot",Obj("batteryPercent",0,"charging",false,"sleepMinutes",3,"lowBatteryThreshold",20,"pollingRate",8000));}
 [STAThread] public static void Main(){try{Run();}catch(Exception error){for(var current=error;current!=null;current=current.InnerException)Console.WriteLine(current.GetType().Name+": "+current.Message);Environment.ExitCode=1;}}
 static void Run(){
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);var states=(Dictionary<string,Dictionary<string,object>>)Field(window,"gearStates");
  foreach(string kind in new[]{"keyboard","mouse","headset"})foreach(int width in new[]{1180,1538,2560}){
   states[kind]=State(kind);var root=Render(window,kind,"电量",width);var nodes=Walk(root).ToArray();var labels=nodes.OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("0%"),"A real zero battery is retained");Check(labels.Any(t=>t.Contains("睡眠模式")),"Original power row is present");Check(nodes.OfType<Image>().Count()==0,"Power page has no product photo column");var combos=nodes.OfType<ComboBox>().Where(c=>c.Items.Contains("3 分钟")||c.Items.Contains("20%")).ToArray();Check(combos.Length==2,"Two separate power settings retain their positions");Check(combos.All(c=>!c.IsEnabled),"Render-only editors cannot apply or edit hardware");Check(nodes.OfType<Button>().Where(b=>Convert.ToString(b.Content)=="应用").All(b=>!b.IsEnabled),"No render-only Apply is enabled");foreach(var combo in combos){Point point=combo.TranslatePoint(new Point(),(UIElement)root);Check(point.X>=248&&point.X+combo.ActualWidth<=width,"Power choices remain in the content area");}Check(new System.Windows.Interop.WindowInteropHelper(window).Handle==IntPtr.Zero,"GUI checks create no native window");
  }
  var state=State("keyboard");states["keyboard"]=state;var polling=Walk(Render(window,"keyboard","性能",1538)).OfType<ComboBox>().Single(c=>c.Items.Contains("8000"));Check(polling.Items.Contains("1000")&&!polling.Items.Contains("2000")&&!polling.Items.Contains("4000"),"Polling options are limited to the verified model options");
  var snapshot=(Dictionary<string,object>)state["snapshot"];foreach(object invalid in new object[]{true,"3",3.0,-1,11,null}){snapshot["sleepMinutes"]=invalid;Check(Invoke(window,"GearPowerDraft","keyboard","sleepMinutes",state)==null,"Invalid or unverified getter cannot create a draft");}snapshot["sleepMinutes"]=3;
  var draft=(GearPowerFieldDraft)Invoke(window,"GearPowerDraft","keyboard","sleepMinutes",state);draft.Value=5;Check((int)snapshot["sleepMinutes"]==3,"Local draft never edits the observed snapshot");Check(!(bool)Invoke(window,"GearPowerMayApply",draft),"Default session cannot write a draft");
  var restored=new Dictionary<string,GearPowerFieldDraft>{{"keyboard:sleepMinutes",draft}};Invoke(window,"RestoreGearPowerDrafts",restored);var copies=(Dictionary<string,GearPowerFieldDraft>)Field(window,"gearPowerDrafts");Check(copies.ContainsKey("keyboard:sleepMinutes")&&copies["keyboard:sleepMinutes"].Value==5,"Valid local draft survives a preview reload");Check(!Object.ReferenceEquals(copies["keyboard:sleepMinutes"],draft),"Restored draft is detached from its transport object");
  draft.DeviceId="different-device";Invoke(window,"RestoreGearPowerDrafts",restored);Check(copies.Count==0,"A draft cannot move to a different device");draft.DeviceId="synthetic-keyboard";draft.Value=11;Invoke(window,"RestoreGearPowerDrafts",restored);Check(copies.Count==0,"Unsupported draft values are rejected");draft.Value=5;snapshot["sleepMinutes"]=2;Invoke(window,"RestoreGearPowerDrafts",restored);Check(copies.Count==0,"A changed observed baseline invalidates the restored draft");snapshot["sleepMinutes"]=3;state["online"]=false;Invoke(window,"RestoreGearPowerDrafts",restored);Check(copies.Count==0,"Offline cached state cannot restore an editable draft");
  var offline=Walk(Render(window,"keyboard","电量",1538)).ToArray();Check(!offline.OfType<TextBlock>().Any(t=>t.Text=="0%"),"Offline cached battery is not presented as current");Check(offline.OfType<ComboBox>().Where(c=>c.Items.Contains("3 分钟")||c.Items.Contains("20%")).All(c=>c.SelectedIndex==0&&!c.IsEnabled),"Offline selections remain unknown");
  state["online"]=true;state["settingOptions"]=Obj("pollingRates",new[]{2000,4000});var unknownPolling=Walk(Render(window,"keyboard","性能",1538)).OfType<ComboBox>().Single(c=>c.Width==200);Check(unknownPolling.Items.Count==1&&unknownPolling.SelectedIndex==0,"Unverified polling-rate options never become controls");
  var headset=State("headset");headset["setCapabilities"]=new[]{"sleepMinutes","lowBatteryThreshold","lowBatteryVoicePrompt"};var headsetSnapshot=(Dictionary<string,object>)headset["snapshot"];headsetSnapshot["lowBatteryVoicePrompt"]=true;states["headset"]=headset;Set(window,"gearPowerVoiceExpanded",true);var expanded=Walk(Render(window,"headset","电量",1538)).ToArray();var disableVoice=expanded.OfType<CheckBox>().Single(c=>Convert.ToString(c.Content)=="关闭低电量语音提示。");Check(disableVoice.IsChecked==false&&!disableVoice.IsEnabled,"Disable-voice UI inversely reflects the observed enabled flag");var voice=new GearPowerVoiceDraft{DeviceId="synthetic-headset",Baseline=true,Value=false};Invoke(window,"RestoreGearPowerVoiceDraft",voice);var restoredVoice=(GearPowerVoiceDraft)Field(window,"gearPowerVoiceDraft");Check(restoredVoice!=null&&!restoredVoice.Value&&!Object.ReferenceEquals(restoredVoice,voice),"Voice draft survives reload as detached local data");voice.DeviceId="other-headset";Invoke(window,"RestoreGearPowerVoiceDraft",voice);Check(Field(window,"gearPowerVoiceDraft")==null,"Voice draft cannot transfer device identity");voice.DeviceId="synthetic-headset";headsetSnapshot["lowBatteryVoicePrompt"]=false;Invoke(window,"RestoreGearPowerVoiceDraft",voice);Check(Field(window,"gearPowerVoiceDraft")==null,"Changed voice baseline invalidates a restored draft");headsetSnapshot["lowBatteryVoicePrompt"]=true;headset["online"]=false;Invoke(window,"RestoreGearPowerVoiceDraft",voice);Check(Field(window,"gearPowerVoiceDraft")==null,"Offline state cannot restore a voice draft");var unknownVoice=Walk(Render(window,"headset","电量",1538)).OfType<CheckBox>().Single(c=>Convert.ToString(c.Content)=="关闭低电量语音提示。");Check(unknownVoice.IsChecked==null&&!unknownVoice.IsEnabled,"Offline voice state remains unknown");
  var worker=(WorkerClient)Field(window,"gearWorker");Check(typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"All rendering and draft checks finish without a device worker");Console.WriteLine("Gear power GUI: "+checks+" checks passed. Synthetic data only; no native window or hardware writes.");app.Shutdown();
 }
}
